solution.solution.cpp:
#include <string>

enum class Action { TryAgainLater, Reconnect, GiveUp };

std::string errorName(int code)
{
    switch (code)
    {
    case 10004: return "WSAEINTR";
    case 10035: return "WSAEWOULDBLOCK";
    case 10048: return "WSAEADDRINUSE";
    case 10051: return "WSAENETUNREACH";
    case 10053: return "WSAECONNABORTED";
    case 10054: return "WSAECONNRESET";
    case 10060: return "WSAETIMEDOUT";
    case 10061: return "WSAECONNREFUSED";
    case 10065: return "WSAEHOSTUNREACH";
    default: return "WSA error " + std::to_string(code);
    }
}

Action actionFor(int code)
{
    switch (code)
    {
    case 10004: case 10035: return Action::TryAgainLater;
    case 10053: case 10054: case 10060: case 10061: case 10051: case 10065: return Action::Reconnect;
    default: return Action::GiveUp;
    }
}

unitTests:
TEST("names") {
    CHECK_EQ(errorName(10054), std::string("WSAECONNRESET"));
    CHECK_EQ(errorName(10061), std::string("WSAECONNREFUSED"));
    CHECK_EQ(errorName(10035), std::string("WSAEWOULDBLOCK"));
    CHECK_EQ(errorName(12345), std::string("WSA error 12345"));
}
TEST("actions") {
    CHECK(actionFor(10035) == Action::TryAgainLater);
    CHECK(actionFor(10004) == Action::TryAgainLater);
    CHECK(actionFor(10054) == Action::Reconnect);
    CHECK(actionFor(10060) == Action::Reconnect);
    CHECK(actionFor(10061) == Action::Reconnect);
    CHECK(actionFor(10065) == Action::Reconnect);
    CHECK(actionFor(10048) == Action::GiveUp);
    CHECK(actionFor(10013) == Action::GiveUp);
}

